begin;
create table public.accounts (id uuid primary key references auth.users(id) on delete cascade,role text not null default 'user' check(role in ('user','admin','owner')),trial_started_at timestamptz,trial_end timestamptz,pro_until timestamptz,created_at timestamptz not null default now());
create table public.scenarios (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name)<=160),patch text not null,payload jsonb not null check(pg_column_size(payload)<=100000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.scenario_shares (token uuid primary key default gen_random_uuid(),scenario_id uuid not null references public.scenarios(id) on delete cascade,owner_id uuid not null references auth.users(id),created_at timestamptz default now());
create table public.billing_config (id int primary key check(id=1),config jsonb not null default '{"enabled":false,"sandbox_approved":false,"provider":"stripe","monthly_id":"","annual_id":"","currency":"BRL"}');
insert into public.billing_config(id) values(1);
create table public.subscriptions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),provider text not null,external_id text not null,status text not null,period_end timestamptz,event_at timestamptz not null default now(),unique(provider,external_id));
create table public.webhook_events (provider text not null,event_id text not null,received_at timestamptz default now(),processed_at timestamptz,payload_hash text not null,primary key(provider,event_id));
create table public.audit_log (id bigint generated always as identity primary key,actor uuid,event text not null,detail jsonb not null default '{}',at timestamptz not null default now());
create table public.coverage_records (id uuid primary key default gen_random_uuid(),patch text not null,entity text not null,effect text not null,status text not null check(status in ('static','testing','verified','missing')),source text,fixture text,reviewed_at timestamptz,unique(patch,entity,effect),check(status<>'verified' or (source is not null and fixture is not null and reviewed_at is not null)));
create table public.telemetry_daily (day date not null,user_id uuid not null references auth.users(id),simulations int default 0,failures int default 0,primary key(day,user_id));
alter table public.accounts enable row level security;
alter table public.scenarios enable row level security;
alter table public.scenario_shares enable row level security;
alter table public.billing_config enable row level security;
alter table public.subscriptions enable row level security;
alter table public.webhook_events enable row level security;
alter table public.audit_log enable row level security;
alter table public.coverage_records enable row level security;
alter table public.telemetry_daily enable row level security;
revoke all on public.accounts,public.scenarios,public.scenario_shares,public.billing_config,public.subscriptions,public.webhook_events,public.audit_log,public.coverage_records,public.telemetry_daily from anon,authenticated;
grant select on public.accounts,public.subscriptions to authenticated;
grant select,insert,update,delete on public.scenarios to authenticated;
grant select on public.coverage_records to anon,authenticated;
create policy account_self on public.accounts for select to authenticated using(id=(select auth.uid()));
create policy subscription_self on public.subscriptions for select to authenticated using(user_id=(select auth.uid()));
create policy scenario_self on public.scenarios for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy coverage_public on public.coverage_records for select to anon,authenticated using(true);
create or replace function public.new_account() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.accounts(id) values(new.id);return new;end;$$;
create trigger new_auth_user after insert on auth.users for each row execute function public.new_account();
insert into public.accounts(id) select id from auth.users on conflict do nothing;
create or replace function public.my_entitlement() returns jsonb language plpgsql stable security definer set search_path='' as $$declare a public.accounts;begin if auth.uid() is null then raise exception 'Authentication required';end if;select * into a from public.accounts where id=auth.uid();return jsonb_build_object('role',a.role,'trial_end',a.trial_end,'pro_until',a.pro_until,'pro',a.role in ('admin','owner') or coalesce(a.trial_end>now(),false) or coalesce(a.pro_until>now(),false));end;$$;
create or replace function public.activate_trial() returns jsonb language plpgsql security definer set search_path='' as $$declare a public.accounts;begin if auth.uid() is null then raise exception 'Authentication required';end if;select * into a from public.accounts where id=auth.uid() for update;if a.trial_started_at is not null then raise exception 'Trial already activated';end if;update public.accounts set trial_started_at=now(),trial_end=now()+interval '14 days' where id=auth.uid();insert into public.audit_log(actor,event) values(auth.uid(),'trial_activated');return public.my_entitlement();end;$$;
create or replace function public.require_admin() returns void language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null or not exists(select 1 from public.accounts where id=auth.uid() and role in ('owner','admin')) then raise exception 'Forbidden';end if;end;$$;
create or replace function public.admin_overview() returns jsonb language plpgsql security definer set search_path='' as $$begin perform public.require_admin();return jsonb_build_object('accounts',(select coalesce(jsonb_agg(x),'[]') from (select id,role,trial_end,pro_until from public.accounts order by created_at desc limit 100)x),'subscriptions',(select coalesce(jsonb_agg(x),'[]') from (select * from public.subscriptions order by event_at desc limit 100)x),'audit',(select coalesce(jsonb_agg(x),'[]') from (select * from public.audit_log order by at desc limit 100)x),'billing',(select config from public.billing_config where id=1),'coverage',(select coalesce(jsonb_agg(x),'[]') from public.coverage_records x),'telemetry',(select coalesce(jsonb_agg(x),'[]') from (select day,sum(simulations) simulations,sum(failures) failures from public.telemetry_daily group by day order by day desc limit 30)x));end;$$;
create or replace function public.admin_configure_billing(config jsonb) returns void language plpgsql security definer set search_path='' as $$begin perform public.require_admin();if config->>'provider' not in ('stripe','asaas','mercadopago') then raise exception 'Invalid provider';end if;if coalesce((config->>'enabled')::boolean,false) then raise exception 'Enabling requires an audited sandbox release via server procedure';end if;update public.billing_config set config=admin_configure_billing.config where id=1;insert into public.audit_log(actor,event,detail) values(auth.uid(),'billing_updated',jsonb_build_object('provider',config->>'provider'));end;$$;
create or replace function public.create_share(scenario_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare t uuid;begin if not exists(select 1 from public.scenarios s where s.id=scenario_id and s.owner_id=auth.uid()) then raise exception 'Forbidden';end if;insert into public.scenario_shares(scenario_id,owner_id) values(scenario_id,auth.uid()) returning token into t;return t;end;$$;
create or replace function public.read_shared(share_token uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('name',s.name,'patch',s.patch,'payload',s.payload) from public.scenario_shares t join public.scenarios s on s.id=t.scenario_id where t.token=share_token;$$;
create or replace function public.revoke_share(share_token uuid) returns void language sql security definer set search_path='' as $$delete from public.scenario_shares where token=share_token and owner_id=auth.uid();$$;
create or replace function public.record_telemetry(failed boolean default false) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then return;end if;insert into public.telemetry_daily(day,user_id,simulations,failures) values(current_date,auth.uid(),1,case when failed then 1 else 0 end) on conflict(day,user_id) do update set simulations=least(10000,public.telemetry_daily.simulations+1),failures=least(10000,public.telemetry_daily.failures+case when failed then 1 else 0 end);end;$$;
revoke execute on function public.new_account(),public.my_entitlement(),public.activate_trial(),public.require_admin(),public.admin_overview(),public.admin_configure_billing(jsonb),public.create_share(uuid),public.read_shared(uuid),public.revoke_share(uuid),public.record_telemetry(boolean) from public,anon,authenticated;
grant execute on function public.my_entitlement(),public.activate_trial(),public.admin_overview(),public.admin_configure_billing(jsonb),public.create_share(uuid),public.revoke_share(uuid),public.record_telemetry(boolean) to authenticated;
grant execute on function public.read_shared(uuid) to anon,authenticated;
grant all on public.accounts,public.scenarios,public.scenario_shares,public.billing_config,public.subscriptions,public.webhook_events,public.audit_log,public.coverage_records,public.telemetry_daily to service_role;
grant usage,select on sequence public.audit_log_id_seq to service_role;
create index scenarios_owner on public.scenarios(owner_id,created_at desc);
create index audit_at on public.audit_log(at desc);
commit;
